import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.XXezeKOl.js";const m=JSON.parse('{"title":"记忆读写策略与方案对比","description":"记忆什么时候读、什么时候写、怎么遗忘，以及摘要、向量、画像、mem0 类记忆层和框架内置存储的取舍。","frontmatter":{"title":"记忆读写策略与方案对比","description":"记忆什么时候读、什么时候写、怎么遗忘，以及摘要、向量、画像、mem0 类记忆层和框架内置存储的取舍。"},"headers":[],"relativePath":"guide/08-memory/memory-strategy.md","filePath":"guide/08-memory/memory-strategy.md","lastUpdated":null}'),r={name:"guide/08-memory/memory-strategy.md"};function l(i,t,o,d,p,u){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="记忆读写策略与方案对比" tabindex="-1">记忆读写策略与方案对比 <a class="header-anchor" href="#记忆读写策略与方案对比" aria-label="Permalink to &quot;记忆读写策略与方案对比&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>掌握记忆&quot;读、写、忘&quot;三个环节各自的可选策略</li><li>能对比摘要记忆、向量记忆、结构化画像、图记忆等方案的优缺点</li><li>了解 mem0、Letta、LangGraph Store 等开源方案的定位</li><li>能根据业务场景组合出合适的记忆架构</li></ul></div><p>前三篇分别讲了 <a href="/guide/08-memory/memory-types">记忆的分类</a>、<a href="/guide/08-memory/short-term">短期记忆</a> 和 <a href="/guide/08-memory/long-term">长期记忆</a>。这一篇不写新代码，而是站高一层：把各种做法放在一起比较，帮你在真实项目里做选择。本文是概念性文章，没有可运行代码。</p><h2 id="读策略-记忆什么时候进入上下文" tabindex="-1">读策略：记忆什么时候进入上下文 <a class="header-anchor" href="#读策略-记忆什么时候进入上下文" aria-label="Permalink to &quot;读策略：记忆什么时候进入上下文&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>总是注入</td><td>每次请求都把画像 / 摘要拼进 system prompt</td><td>简单、确定，不会漏</td><td>占用固定 Token；内容多了就不可行</td></tr><tr><td>每轮检索</td><td>用当前用户输入去检索 Top-K 记忆再注入</td><td>只带相关内容，可扩展到海量记忆</td><td>每轮多一次检索；检索不准就会带入噪声</td></tr><tr><td>按需调用</td><td>提供 <code>search_memory</code> 工具，模型自己决定是否查</td><td>不需要时零开销，灵活</td><td>依赖模型判断，可能该查的时候不查</td></tr></tbody></table><p>实践中常见的组合是：<strong>小而关键的画像总是注入，大量的情景记忆每轮检索或按需调用</strong>。</p><p>&quot;每轮检索&quot;还有个细节：直接拿用户这一句话去检索，效果经常不好。比如用户说&quot;那第二种呢？&quot;，这句话本身几乎没有语义信息。可以先用 LLM 结合最近几轮对话把它改写成完整的查询，再去检索。这和 RAG 中的查询改写是同一个思路。</p><h2 id="写策略-什么时候写、写成什么样" tabindex="-1">写策略：什么时候写、写成什么样 <a class="header-anchor" href="#写策略-什么时候写、写成什么样" aria-label="Permalink to &quot;写策略：什么时候写、写成什么样&quot;">​</a></h2><p><strong>写入时机</strong>：</p><ul><li><strong>热路径同步写</strong>：每轮对话后立即提取。实时，但增加延迟，且只看到局部信息。</li><li><strong>后台异步写</strong>：会话结束或闲置后批量提取。不影响响应，看到的上下文更完整，是多数产品的选择。</li><li><strong>显式触发</strong>：用户说&quot;记住……&quot;或模型调用 <code>save_memory</code> 工具时写入。</li></ul><p><strong>写入形态</strong>，按加工程度从低到高：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始对话  ──►  摘要  ──►  事实条目  ──►  结构化画像 / 知识图谱</span></span>
<span class="line"><span> (信息全)                                    (信息少，但最干净、最易用)</span></span>
<span class="line"><span> (噪声多)                                    (加工成本最高)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>加工得越多，读取时越好用，但信息损失越大，写入成本也越高。一个稳妥的做法是：<strong>原始对话归档保存（用于审计和重新提取），上下文里只用加工后的形态</strong>。这样当提取逻辑升级时，可以从原始数据重新生成记忆。</p><h2 id="遗忘策略-记忆也需要清理" tabindex="-1">遗忘策略：记忆也需要清理 <a class="header-anchor" href="#遗忘策略-记忆也需要清理" aria-label="Permalink to &quot;遗忘策略：记忆也需要清理&quot;">​</a></h2><p>很多人只考虑&quot;怎么记住&quot;，忘了&quot;怎么忘掉&quot;。记忆只增不减，迟早会出现过时信息、矛盾信息和大量低价值噪声。</p><ul><li><strong>覆盖</strong>：同一属性出现新值时替换旧值。画像天然支持；记忆条目需要在写入时先检索相似条目，让 LLM 判断是新增、更新、删除还是忽略。</li><li><strong>衰减</strong>：检索打分里加入时近性，旧记忆的权重逐渐降低，但数据仍在。</li><li><strong>过期（TTL）</strong>：给某些类型的记忆设有效期，例如&quot;用户这周在出差&quot;。</li><li><strong>合并（Consolidation）</strong>：定期让 LLM 把大量零碎条目整理成少量高层结论，类似人在睡眠中整理记忆。Generative Agents 中的&quot;反思（Reflection）&quot;就是这种机制。</li><li><strong>用户删除</strong>：用户主动要求删除的记忆必须真正删除，包括向量索引里的副本。</li></ul><h2 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to &quot;方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>写入</th><th>读取</th><th>优点</th><th>缺点</th><th>适合场景</th></tr></thead><tbody><tr><td>滑动窗口</td><td>无需加工</td><td>最近 N 轮全量</td><td>零成本、零失真</td><td>早期信息全丢</td><td>短对话、闲聊</td></tr><tr><td>摘要记忆</td><td>LLM 滚动压缩</td><td>摘要全量注入</td><td>实现简单，保留主线</td><td>细节丢失，多次压缩会漂移</td><td>单会话内的长对话</td></tr><tr><td>向量记忆</td><td>对话片段或事实做 Embedding</td><td>语义检索 Top-K</td><td>能扩展到海量记忆</td><td>不擅长精确事实和冲突处理；检索噪声</td><td>情景记忆、&quot;上次那件事&quot;</td></tr><tr><td>结构化画像</td><td>LLM 提取 → 字段覆盖</td><td>按用户 ID 全量读取</td><td>精确、可解释、天然去重</td><td>需要设计字段；不适合存事件</td><td>偏好、身份、技术栈</td></tr><tr><td>图记忆</td><td>抽取实体和关系写入图</td><td>图遍历 + 检索</td><td>能表达关系和时间变化，支持多跳</td><td>抽取成本高、实现复杂</td><td>关系复杂的长期助手、CRM</td></tr><tr><td>记忆层服务（mem0 类）</td><td>LLM 提取事实并自动去重更新</td><td>API 检索</td><td>开箱即用，省去自研</td><td>引入外部依赖；提取逻辑是黑盒</td><td>想快速上线长期记忆</td></tr><tr><td>框架内置存储</td><td>框架约定的接口</td><td>框架约定的接口</td><td>与框架深度集成</td><td>与框架绑定</td><td>已经使用该框架的项目</td></tr></tbody></table><h2 id="开源方案速览" tabindex="-1">开源方案速览 <a class="header-anchor" href="#开源方案速览" aria-label="Permalink to &quot;开源方案速览&quot;">​</a></h2><p>下面只做定位层面的介绍，具体 API 和功能变化较快，以各项目官方文档为准。</p><ul><li><strong>mem0</strong>：一个面向 Agent 的记忆层，提供开源库和托管服务。核心思路是用 LLM 从对话中提取事实，与已有记忆比对后决定新增、更新或删除，底层可接多种向量库，也支持图存储。和上一篇手写的&quot;变更集&quot;思路一致，只是更完善。</li><li><strong>Letta（原 MemGPT）</strong>：把上下文窗口当作&quot;内存&quot;、外部存储当作&quot;磁盘&quot;。Agent 通过工具调用自主编辑常驻上下文的记忆块，并把不常用的信息换出到外部存储。适合想让 Agent 自主管理记忆的场景。</li><li><strong>Zep / Graphiti</strong>：基于时序知识图谱的记忆方案，强调事实随时间的变化（某个关系何时成立、何时失效）。Graphiti 是其开源的图谱构建库。</li><li><strong>LangGraph</strong>：区分两层。Checkpointer 按线程（thread）持久化图的状态，相当于短期记忆；Store 提供跨线程的键值 / 语义检索存储，用于长期记忆。详见 <a href="/guide/11-frameworks/langgraph">LangGraph</a>。</li><li><strong>其他框架</strong>：LlamaIndex、OpenAI Agents SDK、Spring AI、LangChain4j 等也都提供会话记忆相关的抽象，多数聚焦于对话历史管理，长期记忆通常需要自己接存储。见 <a href="/guide/11-frameworks/overview">框架全景与选型</a>。</li></ul><p>选择第三方方案前，问自己三个问题：数据存在哪里、能否私有化部署？提取逻辑能否定制和评估？出问题时能否看到&quot;为什么记住了这条 / 为什么没检索到&quot;？</p><h2 id="按场景组合" tabindex="-1">按场景组合 <a class="header-anchor" href="#按场景组合" aria-label="Permalink to &quot;按场景组合&quot;">​</a></h2><p>没有一种方案能包打天下，真实系统基本都是组合。下面是几个典型场景的参考架构：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景 A：客服机器人（单次会话为主）</span></span>
<span class="line"><span>  短期：滑动窗口（最近 10 轮）+ 关键字段（订单号、手机号）结构化保存</span></span>
<span class="line"><span>  长期：几乎不需要；历史工单从业务系统查询，而不是靠&quot;记忆&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景 B：个人助理 / 陪伴类应用（跨会话、强个性化）</span></span>
<span class="line"><span>  短期：最近 N 轮原文 + 滚动摘要</span></span>
<span class="line"><span>  长期：结构化画像（每次注入）+ 情景记忆向量库（每轮检索，带时近性）</span></span>
<span class="line"><span>  后台：会话结束后提取；定期合并精简</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景 C：Coding Agent（长任务、项目级）</span></span>
<span class="line"><span>  短期：上下文压缩 + 工具结果截断 + 计划清单外置到文件</span></span>
<span class="line"><span>  长期：项目规则文件（程序记忆，人可编辑）+ 少量用户偏好</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>一个容易被忽视的原则：<strong>能从业务系统查到的，不要放进记忆</strong>。订单状态、账户余额这类信息有权威数据源，应该通过 Tool Calling 实时查询。记忆里的副本会过时，而且不可信。</p><p>选型时可以按下面的顺序思考：</p><ol><li>是否真的需要跨会话记忆？很多场景短期记忆就够了。</li><li>需要记住的信息是&quot;每次都用&quot;还是&quot;偶尔用&quot;？前者用画像，后者用检索。</li><li>信息之间是否有复杂关系、是否随时间变化？是的话考虑图记忆。</li><li>团队是否有精力自研和评估？没有的话可以先用成熟的记忆层服务，但要确认数据合规。</li></ol><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>过早上复杂方案</strong>：还没验证用户需要记忆，就上图数据库和多级记忆。先用画像 + 摘要跑通，再根据 bad case 加能力。</li><li><strong>记忆与业务数据重复</strong>：把可以实时查询的数据存成记忆，导致记忆和数据库不一致。</li><li><strong>只看单次效果</strong>：记忆系统的问题往往在几十次会话后才暴露，例如画像膨胀、矛盾累积。评估时要模拟长期使用。</li><li><strong>检索结果全部注入</strong>：Top-K 里可能有低分噪声，设置相似度阈值，宁缺毋滥。</li><li><strong>黑盒方案不可排查</strong>：用第三方记忆层时，要能导出、查看、删除记忆，否则用户投诉&quot;它为什么这么说&quot;时无从下手。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><p><strong>1.</strong> 为什么建议保留原始对话归档，即使上下文里只用加工后的记忆？</p><details class="details custom-block"><summary>查看答案</summary><p>加工（摘要、提取）会丢信息，而且提取逻辑会不断迭代。保留原始数据，可以在提取逻辑升级后重新生成记忆，也便于审计和排查问题。注意归档本身也要遵守隐私和删除要求。</p></details><p><strong>2.</strong> 某电商客服 Agent 想&quot;记住用户的订单状态&quot;，应该怎么做？</p><details class="details custom-block"><summary>查看答案</summary><p>不应该把订单状态写进记忆。订单状态的权威来源是订单系统，且会实时变化，应该提供查询工具，在需要时实时查询。记忆里最多保存&quot;用户最近咨询过的订单号&quot;这类线索。</p></details><p><strong>3.</strong> 向量记忆和结构化画像分别更擅长什么？</p><details class="details custom-block"><summary>查看答案</summary><p>向量记忆擅长在大量非结构化内容中按语义找相关信息，适合情景记忆；结构化画像擅长存储精确、需要覆盖更新的事实和偏好，读取确定、无需检索，适合每次都要用的信息。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://github.com/mem0ai/mem0" target="_blank" rel="noreferrer">mem0（GitHub）</a></li><li><a href="https://github.com/letta-ai/letta" target="_blank" rel="noreferrer">Letta（GitHub）</a></li><li><a href="https://github.com/getzep/graphiti" target="_blank" rel="noreferrer">Graphiti（GitHub）</a></li><li><a href="https://langchain-ai.github.io/langgraph/concepts/memory/" target="_blank" rel="noreferrer">LangGraph 文档：Memory</a></li><li><a href="https://arxiv.org/abs/2310.08560" target="_blank" rel="noreferrer">MemGPT 论文</a>、<a href="https://arxiv.org/abs/2309.02427" target="_blank" rel="noreferrer">CoALA 论文</a></li><li>本站：<a href="/guide/07-context-engineering/compression">压缩与摘要</a>、<a href="/guide/09-rag/overview">RAG 全景</a></li></ul>`,39)])])}const g=a(r,[["render",l]]);export{m as __pageData,g as default};
